    /* --- HELPER FUNCTIONS --- */
   function getComments(sysId) {
    var list = [];

    var projRec = new GlideRecordSecure('pm_project');
    if (!projRec.get(sysId)) return list;

    // --- Fetch Additional Comments (comments field) ---
    var rawComments = projRec.comments.getJournalEntry(-1);
    if (rawComments && rawComments.trim() !== '') {
        var commentEntries = rawComments.split('\n\n');
        for (var i = 0; i < commentEntries.length; i++) {
            var entry = commentEntries[i].trim();
            if (!entry) continue;

            var firstNewline = entry.indexOf('\n');
            var header = (firstNewline !== -1) ? entry.substring(0, firstNewline) : entry;
            var commentText = (firstNewline !== -1) ? entry.substring(firstNewline + 1).trim() : '';
            var dashIndex = header.indexOf(' - ');
            var createdOn = (dashIndex !== -1) ? header.substring(0, dashIndex).trim() : header;
            var createdBy = (dashIndex !== -1) ? header.substring(dashIndex + 3).trim() : 'Unknown';

            if (commentText) {
                list.push({
                    comment: commentText,
                    created_on: createdOn,
                    created_by_name: createdBy,
                    type: 'comment'  // optional: use this in HTML to style differently
                });
            }
        }
    }

    // --- Fetch Work Notes (notes field) ---
    var rawNotes = projRec.work_notes.getJournalEntry(-1);
    if (rawNotes && rawNotes.trim() !== '') {
        var noteEntries = rawNotes.split('\n\n');
        for (var j = 0; j < noteEntries.length; j++) {
            var noteEntry = noteEntries[j].trim();
            if (!noteEntry) continue;

            var noteNewline = noteEntry.indexOf('\n');
            var noteHeader = (noteNewline !== -1) ? noteEntry.substring(0, noteNewline) : noteEntry;
            var noteText = (noteNewline !== -1) ? noteEntry.substring(noteNewline + 1).trim() : '';
            var noteDash = noteHeader.indexOf(' - ');
            var noteCreatedOn = (noteDash !== -1) ? noteHeader.substring(0, noteDash).trim() : noteHeader;
            var noteCreatedBy = (noteDash !== -1) ? noteHeader.substring(noteDash + 3).trim() : 'Unknown';

            if (noteText) {
                list.push({
                    comment: noteText,
                    created_on: noteCreatedOn,
                    created_by_name: noteCreatedBy,
                    type: 'work_note'  // optional: use this to show a 🔒 or "Internal" badge
                });
            }
        }
    }

    // --- Sort merged list by date descending ---
    list.sort(function(a, b) {
        return new Date(b.created_on) - new Date(a.created_on);
    });

    return list;
}
